head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.EXCEL_NAME = "예탁원의무보유청구내역";    // 엑셀 파일명의 이름 부분 (전환 규칙 42)

// 원본 : 없음(신규 화면) — 퍼블리싱 목업 ULDSTF24802.xml + API 명세 ULDSTF24802_API.md 로 설계했다
/*
 * 화면 동작
 *  - 화면을 열면 의무보유시작일을 다음날로 두고 바로 조회한다(가정 — 결과서 §10 #1).
 *  - 의무보유시작일(필수)·종목코드(선택)로 예탁원 의무보유 청구내역을 조회하고 건수를 적는다.
 *  - 종목 찾기(돋보기)로 종목을 고르면 종목코드·명을 채운다. 조회는 하지 않는다.
 *  - 목록을 엑셀로 내려받는다.
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF24802/ULDSTF24802.md (§번호는 이 문서의 절)
 */

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 30
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF24802.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 30
 * @description 로딩 — 의무보유시작일 기본값(다음날) → 달력 형식 검사·조회 Enter 키 바인딩 → 목록 조회. (§3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 의무보유시작일 기본값 — 오늘 청구되어 다음날부터 의무보유가 시작되는 내역을 본다 (안내 문구 근거, 가정 §10 #1)
    const today = $c.date.getServerDateTime("yyyyMMdd");
    dma_search.set("dutyHdStrtDd", $c.date.addDate(today, 1));

    // 2) 단일 달력 형식 검사(규칙 37)·조회 영역 Enter 키(규칙 22)
    $c.date.checkCalendarFormat(ica_dutyHdStrtDd, "yyyyMMdd", "의무보유시작일");
    $c.win.setEnterKeyEvent(panel_1, scwin.btn_search_onclick);

    // 3) 첫 조회 (가정 §10 #1)
    await scwin.search();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.btn_search_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회 버튼 클릭 (조회 영역 Enter 키도 이 핸들러) (§4)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_search_onclick = async function (e) {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF24802.btn_search_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_isuSearch_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 종목 찾기(돋보기) 버튼 클릭 (§4)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_isuSearch_onclick = async function (e) {
    try {
        await scwin.openIsuPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF24802.btn_isuSearch_onclick" });
    }
};

/**
 * @method
 * @name scwin.ipt_isuCd_onviewchange
 * @author Inswave
 * @date 2026. 10. 30
 * @description 종목코드를 직접 고치면 앞서 고른 종목명을 비운다 — 코드와 명이 어긋나 보이지 않게. (§4)
 * @param {Object} info 변경 정보
 * @returns
 * @hidden N
 */
scwin.ipt_isuCd_onviewchange = function (info) {
    try {
        ipt_isuNm.setValue("");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF24802.ipt_isuCd_onviewchange" });
    }
};

/**
 * @method
 * @name scwin.btn_excel_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 엑셀다운로드 버튼 클릭 (§4)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_excel_onclick = async function (e) {
    try {
        await scwin.excelDown();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF24802.btn_excel_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectList
 * @author Inswave
 * @date 2026. 10. 30
 * @description 예탁원 의무보유 청구내역 조회 — 조회조건은 dma_search 에 바인딩돼 있다. 건수를 적는다. (§5.1)
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.selectList = async function () {
    const sbmOptions = {
        id : "sbm_selectList",
        method : "get",
        action : "/api/listing/lstsrch/ksd-duty-hd/select-list",
        ref : "dma_search",
        target : "dlt_list=body",
        gridview : "grd_list",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀
    if (!result.responseJSON?.success) return false;    // 실패 안내는 공통 오류 핸들러

    spn_totCnt.setValue(dlt_list.getRowCount());
    return true;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회 — 조회조건을 검사하고 통과하면 목록을 조회한다. (§6.1)
 * @returns
 * @hidden N
 */
scwin.search = async function () {
    if (!(await scwin.validateSearch())) return;
    await scwin.selectList();
};

/**
 * @method
 * @name scwin.validateSearch
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회조건 검사 — 의무보유시작일이 8자리로 입력됐는지. 종목코드는 선택 조건이다(가정 §10 #2). (§6.1)
 * @returns {Promise<Boolean>} 통과 여부
 * @hidden N
 */
scwin.validateSearch = async function () {
    const dutyHdStrtDd = String(dma_search.get("dutyHdStrtDd") ?? "");

    if (dutyHdStrtDd.length !== 8) {
        // MSG-A005 "[^] 을(를) 입력하셔야 합니다."
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "의무보유시작일"));
        ica_dutyHdStrtDd.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name scwin.openIsuPopup
 * @author Inswave
 * @date 2026. 10. 30
 * @description 상장종목찾기(ULDSTF92017) — 주권 종목을 골라 종목코드·명에 채운다. 취소·닫기면 그대로 둔다. 조회는 하지 않는다. (§6.2)
 * @returns
 * @hidden N
 */
scwin.openIsuPopup = async function () {
    // TODO: 증권그룹을 주권(ST)으로 두었다 — 의무보유 대상 증권 범위 확인 필요 (§10 #3)
    const result = await $c.lc.popFindIsu($c.lc.glb.SECUGRP_ID_ST);

    // 취소·닫기(X)도 { isCloseButtonClick } 객체가 온다 → 종목코드로 판정한다
    if ($c.util.isEmpty(result?.isuCd)) return;

    dma_search.set("isuCd", result.isuCd);
    ipt_isuNm.setValue(result.isuKorNm ?? "");
};

/**
 * @method
 * @name scwin.excelDown
 * @author Inswave
 * @date 2026. 10. 30
 * @description 목록을 엑셀로 내려받는다. 0건 안내는 공통 함수가 한다. (§6.3)
 * @returns
 * @hidden N
 */
scwin.excelDown = async function () {
    await $c.data.downloadGridViewExcel(grd_list, {
        // 파일명 {menuId}_{이름}_{yyyyMMddHHmmss}.xlsx (전환 규칙 42)
        fileName : $c.win.getProgramId() + "_" + scwin.EXCEL_NAME + "_" + $c.date.getServerDateTime("yyyyMMddHHmmss") + ".xlsx",
        sheetName : "sheet1"
    });
};
